def list_users(self) -> str:
    identity_store_id = self._get_param("IdentityStoreId")
    max_results = self._get_param("MaxResults")
    next_token = self._get_param("NextToken")
    filters = self._get_param("Filters")
    (
        users,
        next_token,
    ) = self.identitystore_backend.list_users(
        identity_store_id=identity_store_id,
        max_results=max_results,
        next_token=next_token,
        filters=filters,
    )

    return json.dumps(
        dict(Users=[self._user_to_dict(u) for u in users], NextToken=next_token)
    )

def _user_to_dict(self, user):
    """Convert User namedtuple to a dictionary suitable for JSON serialization."""
    user_dict = user._asdict()
    if user_dict["Name"]:
        user_dict["Name"] = user_dict["Name"]._asdict()
    return user_dict

